#!/bin/bash
# gen-licenses.sh SRC_LOADER SRC_HEADERS > vulkan-loader-licenses.txt
# Licence/notice record of vulkan-1.dll (Khronos Vulkan-Loader). Reads the checked-out v1.4.366 sources.
set -euo pipefail
L=$1; H=$2
bar() { echo; echo "=============================================================================="; echo "$1"; echo "=============================================================================="; echo; }
cat <<HDR
Licences and notices of vulkan-1.dll (Khronos Vulkan-Loader v1.4.366)
Vulkan-Loader commit 3187e1e4d463ddf7f60f0bbaf26c7d7b7e40ca34, Vulkan-Headers commit 73814d006638aa00bd553215b054f0f02e457e22
Generated by gen-licenses.sh from the sources that build-loader.sh compiles.
vulkan-1.dll is a separate DLL (aggregation with the Mesa lavapipe ICD, which has its own record).
HDR
bar "1. Vulkan-Loader: Apache License 2.0 (majority of files; copyright The Khronos Group Inc., Valve Corporation, LunarG, Inc.)"
cat "$L/LICENSE.txt"
bar "NOTICE (Apache-2.0 section 4(d))"
if [ -e "$L/NOTICE" ] || [ -e "$L/NOTICE.txt" ]; then cat "$L"/NOTICE*; else
  echo "Vulkan-Loader v1.4.366 ships no NOTICE file; there is no NOTICE text to carry. The copyright lines above and below are kept."; fi
bar "2. Vulkan-Headers (compiled in): Apache-2.0 OR MIT, used here under Apache-2.0 (the text of section 1); MIT alternative:"
cat "$H/LICENSES/MIT.txt"
bar "3. loader/cJSON.c, cJSON.h (MIT, Dave Gamble and cJSON contributors)"
sed -n '2,21p' "$L/loader/cJSON.c" | sed 's/^  //'
bar "4. loader/loader_json.c, loader_json.h (MIT, Khronos Group / Valve / LunarG)"
sed -n '2,21p' "$L/loader/loader_json.c" | sed 's/^  //'
bar "5. loader/dirent_on_windows.c, dirent_on_windows.h (Kevlin Henney, HPND-Kevlin-Henney)"
cat "$L/LICENSES/HPND-Kevlin-Henney.txt"
bar "6. Statically linked toolchain runtime (libgcc, mingw-w64 CRT startup): copyright files of the build host packages"
echo "--- mingw-w64-common ---"; cat /usr/share/doc/mingw-w64-common/copyright
echo; echo "--- gcc-mingw-w64-base ---"; cat /usr/share/doc/gcc-mingw-w64-base/copyright
